/**************************
 * Router Detection
 *
 * Determines whether to use App Router or Pages Router based on:
 * - Explicit configuration (config.router)
 * - Directory structure analysis
 * - Route file presence detection
 **************************/
import { basename, dirname, isAbsolute, join, normalize, relative } from "../platform/compat/path/index.js";
import { createFileSystem } from "../platform/compat/fs.js";
import { rendererLogger } from "../utils/index.js";
import { LRUCache } from "../utils/lru-wrapper.js";
import { SpanNames } from "../observability/index.js";
import { withSpan } from "../observability/tracing/otlp-setup.js";
const logger = rendererLogger.component("router-detection");
// Re-export from app-route-resolver for backward compatibility
export { getAppRouteEntity } from "./app-route-resolver.js";
const ROUTER_DETECTION_CACHE_MAX_ENTRIES = 200;
const ROUTER_DETECTION_CACHE_TTL_MS = 60_000;
const routerDetectionCache = new LRUCache({
    maxEntries: ROUTER_DETECTION_CACHE_MAX_ENTRIES,
    ttlMs: ROUTER_DETECTION_CACHE_TTL_MS,
});
let warnedMissingProjectId = false;
/**
 * Clear the router detection cache. Call when filesystem changes.
 * @deprecated Use clearRouterDetectionCacheForProject for multi-tenant deployments
 */
export function clearRouterDetectionCache() {
    routerDetectionCache.clear();
}
/**
 * Clear the router detection cache for a specific project.
 * Use this in multi-tenant deployments to avoid clearing other projects' caches.
 *
 * @param projectId - The project ID used as cache key. Falls back to projectDir for local dev.
 */
export function clearRouterDetectionCacheForProject(projectId) {
    routerDetectionCache.delete(projectId);
}
export function primeRouterDetectionCache(projectKey, mode) {
    routerDetectionCache.set(projectKey, mode === "app");
}
function isPathInside(path, directory) {
    const relativePath = relative(directory, path).replaceAll("\\", "/");
    return relativePath === "" ||
        (relativePath !== ".." &&
            !relativePath.startsWith("../") &&
            !isAbsolute(relativePath));
}
function resolveProjectPath(projectDir, path) {
    return normalize(isAbsolute(path) ? path : join(projectDir, path));
}
/**
 * Resolve the router that owns an already-resolved page.
 *
 * Auto-detection decides which router to try first, but mixed projects can
 * legitimately fall back to the other router. Per-page rendering must follow
 * the route that actually resolved instead of the project-wide preference.
 *
 * Pages routes can also resolve from the project root. App routes cannot
 * resolve outside their configured root, so an unmatched resolved path belongs
 * to the Pages router.
 */
export function resolveRouterModeForPage(projectDir, pagePath, config) {
    if (config.router === "app")
        return "app";
    if (config.router === "pages")
        return "pages";
    const resolvedPagePath = resolveProjectPath(projectDir, pagePath);
    const appRoot = resolveProjectPath(projectDir, config.directories?.app ?? "app");
    const pagesRoot = resolveProjectPath(projectDir, config.directories?.pages ?? "pages");
    const isAppRoute = isPathInside(resolvedPagePath, appRoot);
    const isPagesRoute = isPathInside(resolvedPagePath, pagesRoot);
    if (isAppRoute && isPagesRoute) {
        const appDistance = relative(appRoot, resolvedPagePath).split(/[\\/]/).filter(Boolean).length;
        const pagesDistance = relative(pagesRoot, resolvedPagePath).split(/[\\/]/).filter(Boolean).length;
        return pagesDistance < appDistance ? "pages" : "app";
    }
    if (isAppRoute)
        return "app";
    return "pages";
}
/**
 * Detect if app router should be used based on config and directory structure.
 *
 * In multi-tenant proxy mode, `projectDir` is the same for all projects ("/app"),
 * so the cache key must use `projectId` to avoid cross-project cache poisoning.
 */
export async function detectAppRouter(projectDir, config, adapter, options) {
    if (config?.router === "app")
        return true;
    if (config?.router === "pages")
        return false;
    const cacheKey = options?.projectId ?? projectDir;
    const cached = routerDetectionCache.get(cacheKey);
    if (cached !== undefined)
        return cached;
    if (!options?.projectId && config?.fs?.type === "veryfront-api" && !warnedMissingProjectId) {
        warnedMissingProjectId = true;
        logger.warn("detectAppRouter called without projectId in multi-tenant mode — cache key falls back to projectDir which may cause cross-tenant poisoning", { projectDir });
    }
    return await withSpan(SpanNames.ROUTER_DETECT_APP, async () => {
        const result = await detectAppRouterImpl(projectDir, config, adapter);
        routerDetectionCache.set(cacheKey, result);
        return result;
    }, {
        "router.project_dir": projectDir,
        "router.cache_key": cacheKey,
        "router.config_router": config?.router ?? "auto",
    });
}
async function detectAppRouterImpl(projectDir, config, adapter) {
    const appDirName = config?.directories?.app ?? "app";
    const pagesDirName = config?.directories?.pages ?? "pages";
    const appDir = normalize(join(projectDir, appDirName));
    const pagesDir = normalize(join(projectDir, pagesDirName));
    const [hasAppDir, hasPagesDir] = await Promise.all([
        directoryExists(appDir, projectDir, adapter),
        directoryExists(pagesDir, projectDir, adapter),
    ]);
    if (hasAppDir && (await hasRouteFiles(appDir, adapter)))
        return true;
    if (hasPagesDir && (await hasRouteFiles(pagesDir, adapter)))
        return false;
    if (hasPagesDir && !hasAppDir)
        return false;
    return true;
}
const ROUTE_EXTENSIONS = new Set([".mdx", ".md", ".tsx", ".jsx", ".ts", ".js"]);
const ROUTE_PATTERNS = ["page", "layout", "error", "loading", "not-found", "index"];
async function resolveTraversalKey(dir, adapter, requireCanonicalPath) {
    if (!adapter.fs.realPath) {
        return requireCanonicalPath ? null : normalize(dir);
    }
    try {
        return normalize(await adapter.fs.realPath(dir));
    }
    catch (_) {
        /* expected: virtual adapters may not resolve physical paths */
        return requireCanonicalPath ? null : normalize(dir);
    }
}
async function hasRouteFiles(dir, adapter, visited = new Set(), requireCanonicalPath = false) {
    const traversalKey = await resolveTraversalKey(dir, adapter, requireCanonicalPath);
    if (traversalKey === null || visited.has(traversalKey))
        return false;
    visited.add(traversalKey);
    const entries = await readDirWithFallback(dir, adapter);
    for (const entry of entries) {
        if (entry.isFile) {
            const name = entry.name.toLowerCase();
            const dotIndex = name.lastIndexOf(".");
            const ext = dotIndex === -1 ? "" : name.slice(dotIndex);
            if (ROUTE_EXTENSIONS.has(ext) && ROUTE_PATTERNS.some((pattern) => name.startsWith(pattern))) {
                return true;
            }
            continue;
        }
        if (entry.isDirectory &&
            (await hasRouteFiles(join(dir, entry.name), adapter, visited))) {
            return true;
        }
        if (entry.isSymlink &&
            (await hasRouteFiles(join(dir, entry.name), adapter, visited, true))) {
            return true;
        }
    }
    return false;
}
async function withAdapterFallback(adapterFn, fallbackFn, defaultValue) {
    try {
        return await adapterFn();
    }
    catch (_) {
        /* expected: adapter may not support this operation */
        try {
            return await fallbackFn();
        }
        catch (_) {
            /* expected: fallback may also fail */
            return defaultValue;
        }
    }
}
async function directoryExists(path, projectDir, adapter) {
    if (normalize(path) === normalize(projectDir))
        return true;
    const parentEntries = await readDirWithFallback(dirname(path), adapter);
    const directoryName = basename(path);
    const listed = parentEntries.some((entry) => entry.name === directoryName && (entry.isDirectory || entry.isSymlink));
    if (listed || adapter.id !== "cloudflare")
        return listed;
    // Cloudflare KV represents directories only as key prefixes, so its parent
    // listing can omit a directory that stat can still resolve.
    return Boolean((await statWithFallback(path, adapter))?.isDirectory);
}
async function statWithFallback(path, adapter) {
    const fs = createFileSystem();
    return await withAdapterFallback(async () => (await adapter.fs.stat(path)), async () => {
        const stat = await fs.stat(path);
        return {
            size: stat.size,
            isFile: stat.isFile,
            isDirectory: stat.isDirectory,
            isSymlink: stat.isSymlink,
            mtime: stat.mtime,
        };
    }, null);
}
async function collectDirEntries(iterable) {
    const entries = [];
    for await (const entry of iterable) {
        entries.push({
            name: entry.name,
            isFile: entry.isFile,
            isDirectory: entry.isDirectory,
            isSymlink: entry.isSymlink ?? false,
        });
    }
    return entries;
}
async function readDirWithFallback(dir, adapter) {
    const fs = createFileSystem();
    return await withAdapterFallback(() => collectDirEntries(adapter.fs.readDir(dir)), () => collectDirEntries(fs.readDir(dir)), []);
}
